import fs from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
const script=fs.readFileSync(new URL('../public/script.js',import.meta.url),'utf8');
const master=JSON.parse(fs.readFileSync(new URL('../public/workbook-structure-process-master.json',import.meta.url),'utf8'));
const targetLengths=Object.fromEntries(master.targets.map(t=>[t.code,t.parameters.length]));
assert.deepEqual(targetLengths,{T1:43,T2:42,T3:43,T4:55},'unexpected latest KK counts');
const begin=script.indexOf('function qaApipNormalizeSubCode(value){');
const end=script.indexOf('function qaApipFilesForItem(item,targetFilter=\'all\'){');
assert.ok(begin>0&&end>begin,'index functions must exist');
const snippet=script.slice(begin,end);
const sandbox={workbookEvidenceMaster:master,qaApipEvidenceLocationMap:null,qaApipVariantTargetMap:null,qaApipEvidenceIndex:new Map(),qaApipEvidenceUnmapped:[],qaApipSourceFilesCount:0,qaApipEvidenceFiles:[],qaApipCurrentRow:{opd:'OPD CONTOH'},QA_APIP_GRADE_ORDER:['E','D','C','B','A'],assessmentAllowedTargets:(row)=>row.opd==='OPD CONTOH'?['T1']:row.opd==='BPKAD'?['T1','T2','T3']:['T1','T4'],Map,Set,Array,String,Number,Math,Boolean,Object,console};
vm.createContext(sandbox);
vm.runInContext(snippet+'\nthis.testIndex=qaApipIndexEvidence;this.testFileTargets=qaApipFileTargetCodes;',sandbox);
const variants=[];
for(const group of master.mergedEvidence.groups)for(const v of group.variants||[])variants.push(v);
const keysFor=(target)=>variants.filter(v=>(v.targets||[v.primaryTarget]).includes(target)).map(v=>v.variantKey);
for(const t of ['T1','T2','T3','T4'])assert.ok(keysFor(t).length>0,`no variant ${t}`);
const file=(id,key)=>({uploadId:String(id),evidenceKey:key,fileName:`doc-${id}.pdf`,grade:['A','B','C','D','E'][id%5],fileType:'application/pdf',createdAt:id});
const t1keys=keysFor('T1'),t2keys=variants.filter(v=>v.targets.includes('T2')&&!v.targets.includes('T1')).map(v=>v.variantKey);
const files=Array.from({length:514},(_,i)=>file(i+1,i<181?t1keys[i%t1keys.length]:t2keys[i%t2keys.length]));
// T2 keys must be target-specific rather than variants also including T1.
assert.ok(files.slice(181).every(f=>!variants.find(v=>v.variantKey===f.evidenceKey).targets.includes('T1')),'expected T2-specific test vectors');
sandbox.testIndex(files);
assert.equal(sandbox.qaApipSourceFilesCount,514);
assert.equal(sandbox.qaApipEvidenceFiles.length,514);
assert.equal(sandbox.qaApipEvidenceUnmapped.length,0);
const counts=()=>sandbox.qaApipEvidenceFiles.filter(f=>f.qaLocationValid&&f.qaTargetCodes.some(t=>sandbox.assessmentAllowedTargets(sandbox.qaApipCurrentRow).includes(t))).length;
assert.equal(counts(),181,'OPD scope T1');
sandbox.qaApipCurrentRow={opd:'BPKAD'};
assert.equal(counts(),514,'BPKAD scope T1/T2/T3');
sandbox.qaApipCurrentRow={opd:'INSPEKTORAT'};
assert.equal(counts(),181,'inspektorat scope T1/T4');
sandbox.qaApipCurrentRow={opd:'OPD CONTOH'};
sandbox.testIndex([...files,files[0]]);
assert.equal(sandbox.qaApipEvidenceFiles.length,514,'duplicate upload ID must not double count');
assert.equal(sandbox.qaApipSourceFilesCount,515,'API payload count displayed independently');
// Latest heading is sourced from workbook and restricted by account.
const start2=script.indexOf('function qaApipLiveParameterSource(subCode,paramId){');
const end2=script.indexOf('function qaApipGradeEditor(item,fileUploadId=',start2);
assert.ok(start2>0&&end2>start2);
sandbox.qaApipFilters={target:'all'};
sandbox.QA_APIP_TARGET_LABEL={T1:'KK3.1',T2:'KK3.2',T3:'KK3.3',T4:'KK3.4'};
sandbox.escapeHtml=x=>String(x);
vm.runInContext(script.slice(start2,end2)+'\nthis.testParameterSource=qaApipLiveParameterSource;',sandbox);
const t1=master.targets.find(t=>t.code==='T1').parameters[0];
const k=t1.subCode;const p=t1.paramId;
const source=sandbox.testParameterSource(k,p);
assert.ok(source.length>=1&&source.every(t=>t.code==='T1'));
console.log(JSON.stringify({status:'PASS',latestMasterParameters:targetLengths,sourceUploadFiles:514,scopeOpdGeneral:181,requiresTargetReview:333,scopeBpkad:514,scopeInspektorat:181,duplicateUploadIsDeduplicated:true,latestMappingHeadingScoped:true},null,2));
